    E1, E2, E3, E4
	}

	static class A {
		private EnumSet<E> enumsA;

		public EnumSet<E> getEnumsA() {
			return enumsA;
		}
		public void setEnumsA(EnumSet<E> enumsA) {
			this.enumsA = enumsA;
