		public EnumSet<?> convert(MappingContext<EnumSet<?>, EnumSet<?>> context) {
			Object source = context.getSource();
			if (source == null)
				return null;

			return EnumSet.copyOf((EnumSet<?>) source);
		}

	};

	private ModelMapper initMapperWithPropertyMap() {
